# Runs one batch of the make-an-anime free backend on a Kaggle GPU (T4) with WanGP in headless mode.
# Generated by tools/python/free_backend.py; the tasks are embedded below. Results go to /kaggle/working/results.
import base64, glob, json, os, re, shutil, subprocess, sys, time

ENTRIES = json.loads(base64.b64decode("__ENTRIES_B64__").decode())
WANGP_REF = "f0b54e02aa32b539e7be5c65cf4ada67db69da26"   # the WanGP version the task settings were written for
ATTENTION = "sdpa"
PROFILES = [4, 5]        # WanGP memory profiles to try in order; 5 is the low-RAM fail-safe
GROUP_TIMEOUT = 3 * 3600

T0 = time.time()
WORK = "/kaggle/working"
TMP = "/kaggle/tmp" if os.access("/kaggle", os.W_OK) else "/tmp"
WANGP = f"{TMP}/Wan2GP"
RAW = f"{TMP}/wangp-out"
RES = f"{WORK}/results"
for d in (TMP, RAW, RES):
    os.makedirs(d, exist_ok=True)
REPORT = {"groups": [], "missing": []}


def sh(cmd, check=True, timeout=None):
    print("$", cmd, flush=True)
    try:
        code = subprocess.run(cmd, shell=True, timeout=timeout).returncode
    except subprocess.TimeoutExpired:
        print("[timeout]", flush=True)
        code = 124
    if check and code:
        raise RuntimeError(f"failed ({code}): {cmd}")
    return code


def save_report():
    REPORT["minutes"] = round((time.time() - T0) / 60, 1)
    REPORT["files"] = sorted(os.listdir(RES))
    json.dump(REPORT, open(f"{RES}/_report.json", "w"), indent=1)


# ---- GPU -------------------------------------------------------------------------------------------------------------
smi = subprocess.run("nvidia-smi --query-gpu=name,driver_version,memory.total --format=csv,noheader",
                     shell=True, capture_output=True, text=True).stdout.strip()
print("GPU:", smi or "none")
assert smi, "No GPU: the kernel needs the T4 accelerator."
assert "P100" not in smi, "P100 is not supported by current PyTorch; use T4."
DRIVER = int(smi.splitlines()[0].split(",")[1].strip().split(".")[0])
sh("free -g | head -2; df -h /kaggle/working /tmp | tail -2", check=False)

# ---- WanGP, pinned ---------------------------------------------------------------------------------------------------
if not os.path.exists(f"{WANGP}/wgp.py"):
    sh(f"git clone --filter=blob:none https://github.com/deepbeepmeep/Wan2GP.git {WANGP}")
sh(f"cd {WANGP} && git checkout -q {WANGP_REF} && git log -1 --format='WanGP %h %cd'")
sh("which ffmpeg >/dev/null || (apt-get -qq update && apt-get -qq install -y ffmpeg)")
if DRIVER >= 580:
    TORCH, NEW_STACK = "torch==2.10.0 torchvision==0.25.0 torchaudio==2.10.0 --index-url https://download.pytorch.org/whl/cu130", True
elif DRIVER >= 570:
    TORCH, NEW_STACK = "torch==2.7.1 torchvision==0.22.1 torchaudio==2.7.1 --index-url https://download.pytorch.org/whl/cu128", False
else:
    TORCH, NEW_STACK = "torch==2.7.1 torchvision==0.22.1 torchaudio==2.7.1 --index-url https://download.pytorch.org/whl/cu126", False
sh(f"pip install -q {TORCH}")
import importlib.metadata as md
open(f"{TMP}/constraints.txt", "w").write("\n".join(f"{p}=={md.version(p)}" for p in ("torch", "torchvision", "torchaudio")) + "\n")
reqs = open(f"{WANGP}/requirements.txt").read().splitlines()
if not NEW_STACK:
    reqs = [r for r in reqs if not re.match(r"\s*(--extra-index-url|torchcodec|onnxruntime-gpu)", r)]
open(f"{TMP}/requirements.txt", "w").write("\n".join(reqs) + "\n")
for attempt in range(3):
    if not sh(f"cd {WANGP} && pip install -q -r {TMP}/requirements.txt -c {TMP}/constraints.txt", check=False):
        break
    print(f"Install attempt {attempt + 1} failed; retrying in 30 s."); time.sleep(30)
else:
    for r in reqs:
        r = r.split("#")[0].strip()
        if r and not r.startswith("-"):
            if sh(f"pip install -q '{r}' -c {TMP}/constraints.txt", check=False):
                sh(f"pip install -q --no-deps '{r}' -c {TMP}/constraints.txt", check=False)
print(f"Ready after {(time.time() - T0) / 60:.0f} min.", flush=True)

# ---- inputs from the attached dataset --------------------------------------------------------------------------------
found = {}
for root, _, files in os.walk("/kaggle/input"):
    for f in files:
        found.setdefault(f, os.path.join(root, f))
print(len(found), "input files:", sorted(found)[:40])


def resolve(value):
    if isinstance(value, list):
        return [resolve(v) for v in value]
    if isinstance(value, str) and value.startswith("@@IN@@"):
        name = value[len("@@IN@@"):]
        assert name in found, f"input {name} is not in /kaggle/input"
        return found[name]
    return value


for e in ENTRIES:
    for which in ("task", "fallback"):
        if e.get(which):
            e[which] = {k: resolve(v) for k, v in e[which].items()}


def collect():
    for root, _, files in os.walk(RAW):
        for f in files:
            stem, ext = os.path.splitext(f)
            if ext.lower() in (".png", ".jpg", ".jpeg", ".webp", ".mp4", ".wav", ".mp3", ".flac", ".m4a", ".ogg"):
                shutil.copy2(os.path.join(root, f), f"{RES}/{re.sub(r'[(]\d+[)]$', '', stem).strip()}{ext.lower()}")
    save_report()


def have(stem):
    return any(os.path.splitext(f)[0] == stem for f in os.listdir(RES))


def run_group(model, tasks, label):
    """Run one model's tasks, retrying what is still missing with the next memory profile."""
    info = {"model": model, "label": label, "tasks": len(tasks), "attempts": []}
    REPORT["groups"].append(info)
    for profile in PROFILES:
        todo = [t for t in tasks if not have(t["output_filename"])]
        if not todo:
            break
        path = f"{TMP}/{label}-{model}-p{profile}.json"
        json.dump(todo, open(path, "w"))
        cmd = (f"cd {WANGP} && {sys.executable} wgp.py --process {path} --output-dir {RAW} "
               f"--profile {profile} --attention {ATTENTION} --fp16")
        if sh(cmd + " --dry-run", check=False, timeout=900):
            info["attempts"].append({"profile": profile, "dry_run": "rejected"})
            print(f"WanGP rejected the {model} tasks; skipping this model.", flush=True)
            break
        t = time.time()
        code = sh(cmd, check=False, timeout=GROUP_TIMEOUT)
        collect()
        done = sum(have(x["output_filename"]) for x in tasks)
        info["attempts"].append({"profile": profile, "exit": code, "minutes": round((time.time() - t) / 60, 1), "done": done})
        print(f"[{label}] {model} profile {profile}: exit {code}, {done}/{len(tasks)} done, "
              f"{(time.time() - t) / 60:.1f} min, {(time.time() - T0) / 60:.0f} min so far", flush=True)
        sh("free -g | head -2; nvidia-smi --query-gpu=memory.used,memory.total --format=csv,noheader", check=False)
    save_report()


# ---- generate: one WanGP run per model, in the order the models first appear ------------------------------------------
order = []
for e in ENTRIES:
    if e["task"]["model_type"] not in order:
        order.append(e["task"]["model_type"])
for model in order:
    run_group(model, [e["task"] for e in ENTRIES if e["task"]["model_type"] == model], "main")

# ---- fallbacks for whatever is still missing --------------------------------------------------------------------------
fallbacks = [e["fallback"] for e in ENTRIES if e.get("fallback") and not have(e["task"]["output_filename"])]
for model in dict.fromkeys(t["model_type"] for t in fallbacks):
    run_group(model, [t for t in fallbacks if t["model_type"] == model], "fallback")

REPORT["missing"] = [e["task"]["output_filename"] for e in ENTRIES if not have(e["task"]["output_filename"])]
save_report()
shutil.rmtree(RAW, ignore_errors=True)
sh(f"du -sh {WORK}/*", check=False)
print("RESULT", json.dumps(REPORT)[:3000])
